with flagged as (select *, case when lag(paid_at) over (partition by method order by paid_at, id) is null or paid_at > lag(paid_at) over (partition by method order by paid_at, id) + interval '30' day then 1 else 0 end as is_new_session from payments) select id, order_id, method, amount, paid_at, sum(is_new_session) over (partition by method order by paid_at, id rows between unbounded preceding and current row) as session_no from flagged
